{
  "headline": "Synthetic Portfolio Operational Review",
  "observations": [
    {
      "metric_id": "email_click_rate",
      "interpretation": "Observed email click performance reflects delivered messages with qualifying clicks relative to total delivered messages, noting that known bot clicks are excluded and repeat clicks collapse to message IDs."
    },
    {
      "metric_id": "engagement_rate",
      "interpretation": "Observed engagement rate captures eligible landing sessions meeting qualifying duration, pageview, or registration criteria relative to eligible landing sessions."
    },
    {
      "metric_id": "registration_rate",
      "interpretation": "Observed registration rate indicates eligible landing sessions resulting in a registration relative to total eligible landing sessions, noting that tracking limitations split the hepatitis journey."
    },
    {
      "metric_id": "attendance_rate",
      "interpretation": "Observed attendance rate measures distinct registered webinar or person pairs with positive attendee time relative to total distinct registrations, with rejoins collapsed and presenters excluded."
    }
  ],
  "actions": [
    "Review and add explicit mapping for unmapped hepatitis campaign tags in web exports, preserving original raw tags.",
    "Skip identical webinar export files and count distinct webinar or person pairs rather than attendance rows.",
    "Edit WordPress landing page asset metadata to unhide registration actions at narrow widths and run a fresh mobile test journey."
  ]
}
